import {BOAT_ENDPOINTS} from './layout.js';
import {boatSafeArea} from './camera.js';
const words={boarding:'배에 오르고 있어요',retracting:'출항 준비',departing:'부두를 떠나요',cruise:'바다를 건너는 중',arriving:'선착장에 도착해요',deploying:'내릴 길을 준비해요',disembarking:'천천히 내려요',walkoff:'육지로 걸어가요','waiting-ready':'목적지 선착장을 준비하고 있어요','awaiting-commit':'목적지로 이어가요',reopening:'내릴 길을 다시 열어요',cancelling:'원래 부두로 내려요','motion-free-wait':'움직임 없이 이동 준비','motion-free-arrived':'선착장에 도착했어요'};
export function readBoatSafeArea(stage){const doc=stage.ownerDocument??globalThis.document,w=stage.clientWidth,h=stage.clientHeight,r=stage.getBoundingClientRect?.()??{left:0,top:0,right:w,bottom:h},base=boatSafeArea(w,h,{saveWarning:doc?.body?.dataset?.saveWarning==='true'}),rect=n=>n&&!n.hidden&&(n.getClientRects?.().length??1)?n.getBoundingClientRect?.():null,panels=[rect(stage.querySelector?.('.boat-controls')),rect(doc?.querySelector?.('footer'))].filter(Boolean),top=[rect(doc?.querySelector?.('.topbar')),rect(stage.querySelector?.('.scene-tools'))].filter(Boolean);return{left:base.left,right:base.right,top:Math.max(base.top,...top.map(p=>p.bottom-r.top+12)),bottom:panels.length?Math.max(...panels.map(p=>r.bottom-p.top+8)):base.bottom};}
export function mountBoatControls({stage,controller}){const doc=stage.ownerDocument??globalThis.document,element=doc.createElement('section'),status=doc.createElement('p'),row=doc.createElement('div'),listeners=[];let alive=true;const listen=(node,type,fn,capture=false)=>{node.addEventListener(type,fn,capture);listeners.push([node,type,fn,capture]);};element.className='boat-controls';element.setAttribute('role','group');element.setAttribute('aria-label','배 이동');status.className='boat-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');row.className='boat-buttons';element.append(status,row);
 function button(key,handler){const b=doc.createElement('button');b.type='button';b.setAttribute('data-boat-'+key,'');listen(b,'click',()=>{if(!alive)return;handler();sync();});row.append(b);return b;}
 const pause=button('pause',()=>{if(controller.snapshot()?.paused)controller.resume();else controller.pause();}),action=button('action',()=>controller.cancelOrSkip()),map=button('map',()=>controller.requestMap());
 function sync(){if(!alive)return;const footer=doc.querySelector?.('footer'),fr=footer&&!footer.hidden&&(footer.getClientRects?.().length??1)?footer.getBoundingClientRect?.():null,sr=stage.getBoundingClientRect?.();if(fr&&sr&&Number.isFinite(sr.bottom))element.style.bottom=Math.max(30,sr.bottom-fr.top+8)+'px';const s=controller.snapshot();if(!s){element.hidden=true;return;}element.hidden=!!s.released;status.textContent=(s.paused?'잠시 멈췄어요':words[s.phase]??'배 이동')+' · '+(BOAT_ENDPOINTS[s.to]?.label??'선착장');pause.textContent=s.paused?'계속하기':'잠깐 멈춤';pause.setAttribute('aria-pressed',String(!!s.paused));action.textContent=s.departed?'바로 도착하기':'취소하고 내리기';map.textContent=s.departed?'항해 끝내고 지도':'내리고 지도';action.disabled=!!s.cancelled;map.disabled=!!s.mapQueued;}
 listen(doc,'keydown',event=>{if(!alive||event.repeat||event.ctrlKey||event.altKey||event.metaKey||event.target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;if(event.code==='KeyM'||event.code==='Escape'||event.code==='KeyE'){event.preventDefault();event.stopPropagation();event.code==='KeyM'?controller.requestMap():controller.cancelOrSkip();sync();}},true);
 stage.append(element);stage.setAttribute('data-boat-active','true');sync();return{element,sync,dispose(){if(!alive)return;alive=false;for(const[n,t,fn,c]of listeners)n.removeEventListener(t,fn,c);listeners.length=0;element.remove();stage.setAttribute('data-boat-active','false');}};
}
